mapper.select:
select us.RYJBXXBS as "userId",us.RYBM as "userCode",us.XM as "userName",us.SZDZBDM as "partyCode",p.DZZMC as "partyName",us.XB as "sexId",xb.HZMC as "sex",us.RYZT as "userStatus",ryzt.HZMC as "userStatusName", str_to_date(us.CSRQ,'%Y%m%d') as "birthDate",us.JG as "nativePlace",us.MZ as "nationalId",mz.HZMC as "national",usfb.APPLYDATE as "applyDate",usfb.ACTIVEDATE as "activeDate",usfb.PASSDATE as "passDate", str_to_date(dj.jrzgzzrq,'%Y%m%d') as "inPartyDate", str_to_date(dj.ZZRQ,'%Y%m%d') as "becomeFullDate", usfb.isArchive as "isArchive", case when usfb.isArchive=1 then '是' else '否' end as "isArchiveName", us.xl as educationalId,us.SFZH as idCard,usfb.gradeName,usfb.className,usfb.enrollmentDate,usfb.graduateDate,xl.HZMC as educational, usfb.trainUser1,usfb.trainUser2,usfb.mobile as contactMobile, usfb.isStudent,case when usfb.isStudent=1 then '是' else '否' end as isStudentName,usfb.password,usfb.applyApproveStatus,dic.DICVALUE as applyApproveStatusName, usfb.applyFileReId,usfb.exportDate,usfb.exportPartyName,userinfo.USERNAME as userNo , usfb.archiveDate from VM_RYJBXX_ALL us -- 视图 inner join RS_RYJBXXFB usfb on us.RYBM=usfb.RYBM inner join ZZ_ZZQKXX p on us.szdzbdm=p.dzzdm -- 党组织信息 left join Zzzd_ryzt ryzt on us.ryzt=ryzt.bm -- 人员状态 left join zd_xbm xb on us.xb=xb.bm -- 性别 left join zd_mzdm mz on us.mz=mz.bm -- 民族 left join ZZ_DJXX dj on us.RYBM=dj.RYBM left join zd_whcddm1 xl on us.XL=xl.BM -- 学历 left join cf_dictionary dic on usfb.applyApproveStatus = dic.DICKEY and dic.DICTYPEKEY='ApplyApproveStatus' left join CF_USERS userinfo on us.RYBM=userinfo.USERID where 1=1
and p.dzzdm like concat(#{partyCode},'%')
and us.rybm = #{userCode}
and us.xm like concat('%',#{userName},'%')
and us.ryzt = #{userStatus}
and usfb.APPLYDATE >= #{applyStartDate}
and usfb.APPLYDATE < date_add(#{applyEndDate}, interval 1 day)
and usfb.ACTIVEDATE >= #{activeStartDate}
and usfb.ACTIVEDATE < date_add(#{activeEndDate}, interval 1 day)
and usfb.PASSDATE >= #{passStartDate}
and usfb.PASSDATE < date_add(#{passEndDate}, interval 1 day)
and dj.jrzgzzrq >= date_format(#{inPatyStartDate},'%Y%m%d')
and dj.jrzgzzrq <= date_format(#{inPatyEndDate},'%Y%m%d')
and usfb.IsArchive = #{isArchive}
and (usfb.IsArchive = #{isArchive} or usfb.IsArchive is null)
and usfb.applyApproveStatus = #{applyApproveStatus}
and usfb.gradeName like concat('%',#{gradeName},'%')
and usfb.className like concat('%',#{className},'%')
and us.XB = #{sexId}
and usfb.isStudent = #{isStudent}
and (usfb.isStudent = #{isStudent} or usfb.isStudent is null)
and us.XL = #{educationalId}
and userinfo.USERNAME like concat('%',#{userNo},'%')
order by us.XM,us.RYBM
